"""Before/after table from measure.py timing files. usage: summarize.py before_dir... -- after_dir..."""

import json
import statistics
import sys
from pathlib import Path

args = sys.argv[1:]
cut = args.index("--")
groups = {"before": args[:cut], "after": args[cut + 1 :]}
LABELS = ["x_post", "x_media", "bsky_post", "web", "text"]


def load(dirs):
    out = {}
    for d in dirs:
        for f in Path(d).glob("*.timing.json"):
            t = json.loads(f.read_text())
            out.setdefault(t["label"], []).append(t)
    return out


def step(t, sid, key):
    return next((s[key] for s in t["steps"] if s["id"] == sid), None)


def metrics(t, after):
    v = t["visible_s"]
    first = min(x for x in (v.get("first_post"), v.get("subject")) if x is not None)
    # before: the one Gemini reading lands as the job finishes
    reading = v.get("reading:nemotron-3.5-super-vl") or v.get("assessment") if after else None
    if reading is None:
        reading = step(t, "assess", "end_s") or t["total_s"]
    return {
        "first": first,
        "searches_start": step(t, "copies_x", "start_s"),
        "verify_end": step(t, "verify", "end_s"),
        "reading": reading,
        "done": t["total_s"],
        "reading_ms": t["assessment_latency_ms"],
    }


data = {g: load(d) for g, d in groups.items()}
print("| Input | First facts on screen | Searches start | Copies verified | Reading on screen | Job done |")
print("|---|---|---|---|---|---|")
allm = {"before": [], "after": []}
for lab in LABELS:
    cells = []
    for key in ("first", "searches_start", "verify_end", "reading", "done"):
        parts = []
        for g in ("before", "after"):
            ms = [metrics(t, g == "after")[key] for t in data[g].get(lab, [])]
            ms = [m for m in ms if m is not None]
            parts.append("/".join(f"{m:.1f}" for m in ms) or "-")
        cells.append(f"{parts[0]} → **{parts[1]}**")
    for g in ("before", "after"):
        allm[g] += [metrics(t, g == "after") for t in data[g].get(lab, [])]
    print(f"| {lab} | " + " | ".join(cells) + " |")
for g, ms in allm.items():
    print(
        g,
        "median reading on screen",
        round(statistics.median(m["reading"] for m in ms), 1),
        "median done",
        round(statistics.median(m["done"] for m in ms), 1),
        "median first",
        round(statistics.median(m["first"] for m in ms), 1),
        "reading latency ms",
        sorted(m["reading_ms"] for m in ms if m["reading_ms"]),
    )

